function countEdges(deps) {
  let total = 0;
  for (const name of Object.keys(deps)) total += deps[name].length;
  return total;
}

function dependentsOf(deps, name) {
  return Object.keys(deps).filter((key) => deps[key].includes(name));
}

function isReady(deps, name, done) {
  const needs = deps[name] ?? [];
  return needs.every((need) => done.includes(need));
}

function nodeNames(deps) {
  const seen = new Set(Object.keys(deps));
  for (const name of Object.keys(deps)) {
    for (const need of deps[name]) seen.add(need);
  }
  return [...seen];
}

function readyNow(deps, done) {
  return Object.keys(deps).filter(
    (name) => !done.includes(name) && deps[name].every((need) => done.includes(need)),
  );
}

function hasCycle(deps) {
  const state = new Map();
  function visit(name) {
    if (state.get(name) === "visiting") return true;
    if (state.get(name) === "done") return false;
    state.set(name, "visiting");
    for (const need of deps[name] ?? []) {
      if (visit(need)) return true;
    }
    state.set(name, "done");
    return false;
  }
  return Object.keys(deps).some(visit);
}

function findCycle(deps) {
  const state = new Map();
  const path = [];
  function visit(name) {
    state.set(name, "visiting");
    path.push(name);
    for (const need of deps[name] ?? []) {
      if (state.get(need) === "visiting") {
        return [...path.slice(path.indexOf(need)), need];
      }
      if (!state.has(need)) {
        const found = visit(need);
        if (found) return found;
      }
    }
    path.pop();
    state.set(name, "done");
    return null;
  }
  for (const name of Object.keys(deps)) {
    if (!state.has(name)) {
      const found = visit(name);
      if (found) return found;
    }
  }
  return null;
}

function deployOrder(deps) {
  const state = new Map();
  const order = [];
  function visit(name) {
    if (state.get(name) === "visiting") return false;
    if (state.get(name) === "done") return true;
    state.set(name, "visiting");
    for (const need of deps[name] ?? []) {
      if (!visit(need)) return false;
    }
    state.set(name, "done");
    order.push(name);
    return true;
  }
  for (const name of Object.keys(deps)) {
    if (!visit(name)) return null;
  }
  return order;
}

function stalled(deps) {
  const done = new Set();
  let progress = true;
  while (progress) {
    progress = false;
    for (const name of Object.keys(deps)) {
      if (done.has(name)) continue;
      if (deps[name].every((need) => done.has(need))) {
        done.add(name);
        progress = true;
      }
    }
  }
  return Object.keys(deps).filter((name) => !done.has(name));
}
